const productsByCode = new Map(sourceProducts.map((p) => [String(p.code), p]));
const products = selectedCodes.map((code) => productsByCode.get(code));
if (products.some((p) => !p)) throw new Error("One or more selected products were not found in source data");

const commissionRows = JSON.parse(await fs.readFile(commissionPath, "utf8"));
const commissionById = new Map(commissionRows.slice(1).map((row) => [String(row[6]), { id: String(row[6]), name: String(row[7]), commission: Number(String(row[9]).replace("%", "").replace(",", ".")) / 100 }]));
const input = await FileBlob.load(sourceExportPath);
const workbook = await SpreadsheetFile.importXlsx(input);
const productSheet = workbook.worksheets.getItem("Export Products Sheet");
const groupSheet = workbook.worksheets.getItem("Export Groups Sheet");
const sourceValues = productSheet.getUsedRange().values;
const headers = sourceValues[0];
if (headers.length !== 108) throw new Error(`Expected 108 columns, got ${headers.length}`);

const records = products.map((product) => {
  const categoryId = categoryBySku[product.code];
  const category = commissionById.get(categoryId);
  if (!category) throw new Error(`Commission category ${categoryId} not found for ${product.code}`);
  const pricing = priceFor(product, category);
  return { product, category, pricing, row: rowFor(product, category, pricing, headers) };
});
const publicContentHeaders = ["Назва_позиції", "Назва_позиції_укр", "Пошукові_запити", "Пошукові_запити_укр", "Опис", "Опис_укр", "HTML_заголовок", "HTML_заголовок_укр", "HTML_опис", "HTML_опис_укр"];
const forbiddenPublicToken = /\b(?:U\d+U|AE\s*[-–—]?\s*\d+|SB\s*[-–—]?\s*\d+|XL\s*[-–—]?\s*\d+|AND\s*[-–—]?\s*\d+|MAG\s*[-–—]?\s*728|K16|360\s+Gard|UG\s*[- ]?OPT|supplier|поставщик|source\s*(?:url|code)|internal\s*id)\b/i;
const contentQaHits = [];
for (const record of records) {
  for (const header of publicContentHeaders) {
    const index = headers.indexOf(header);
    const value = index >= 0 ? String(record.row[index] || "") : "";
    if (forbiddenPublicToken.test(value)) contentQaHits.push(`${record.product.code}:${header}`);
  }
}
if (contentQaHits.length) throw new Error(`Forbidden token in public content: ${contentQaHits.join(", ")}`);
const importQaErrors = [];
const productIdentifierIndex = headers.indexOf("Ідентифікатор_товару");
const uniqueIdentifierIndex = headers.indexOf("Унікальний_ідентифікатор");
const categoryIdentifierIndex = headers.indexOf("Ідентифікатор_підрозділу");
const categoryLinkIndex = headers.indexOf("Посилання_підрозділу");
const htmlDescriptionRuIndex = headers.indexOf("HTML_опис");
const htmlDescriptionUaIndex = headers.indexOf("HTML_опис_укр");
for (const record of records) {
  const row = record.row;
  if (!String(row[productIdentifierIndex] || "").trim()) importQaErrors.push(`${record.product.code}:missing product identifier`);
  if (String(row[uniqueIdentifierIndex] || "").trim()) importQaErrors.push(`${record.product.code}:unexpected marketplace unique identifier`);
  if (!String(row[categoryIdentifierIndex] || "").trim()) importQaErrors.push(`${record.product.code}:missing category identifier`);
  if (!String(row[categoryLinkIndex] || "").trim()) importQaErrors.push(`${record.product.code}:missing category link`);
  if (String(row[htmlDescriptionRuIndex] || "").length > 250) importQaErrors.push(`${record.product.code}:RU HTML description too long`);
  if (String(row[htmlDescriptionUaIndex] || "").length > 270) importQaErrors.push(`${record.product.code}:UA HTML description too long`);
}
if (importQaErrors.length) throw new Error(`Import QA failed: ${importQaErrors.join(", ")}`);
const lastCol = colLetter(headers.length - 1);
productSheet.getRange(`A2:${lastCol}515`).clear();
productSheet.getRange(`A1:${lastCol}${records.length + 1}`).values = [headers, ...records.map((r) => r.row)];
productSheet.showGridLines = false; groupSheet.showGridLines = false; productSheet.freezePanes.freezeRows(1); groupSheet.freezePanes.freezeRows(1);
productSheet.getRange(`A1:${lastCol}1`).format = { fill: "#1F4E78", font: { bold: true, color: "#FFFFFF" }, horizontalAlignment: "center", verticalAlignment: "center", wrapText: true };
productSheet.getRange(`A1:${lastCol}1`).format.rowHeight = 38;
productSheet.getRange(`A2:${lastCol}${records.length + 1}`).format = { verticalAlignment: "top", wrapText: true, rowHeight: 92 };
const widths = [16, 38, 40, 44, 44, 58, 58, 12, 12, 10, 12, 18, 14, 18, 72, 12, 12, 12, 28, 22, 22, 18, 18, 18, 18, 18, 18, 18, 24, 18, 14, 18, 22, 24, 18, 18, 12, 18, 38, 38, 58, 58, 18, 18, 12, 12, 12, 12, 18, 14, 28];
for (let i = 51; i < headers.length; i++) widths[i] = i % 3 === 0 ? 24 : i % 3 === 1 ? 10 : 28;
for (let i = 0; i < headers.length; i++) productSheet.getRange(`${colLetter(i)}1:${colLetter(i)}${records.length + 1}`).format.columnWidth = widths[i] || 18;

const pricingSheet = workbook.worksheets.add("Pricing QA");
const pricingHeaders = ["Код", "Товар", "Категорія Prom", "Закупівля UG OPT, грн", "Комісія Prom, %", "Доставка очікувана, грн", "Доставка worst-case, грн", "Мінімальна чиста прибуток, грн", "Цільова чиста прибуток, грн", "Ціна продажу, грн", "Чистий прибуток очікуваний, грн", "Чистий прибуток worst-case, грн", "Ринковий орієнтир, грн", "QA"];
